schemas:
{
  "@context": "https://schema.org",
  "@graph": [
    {
      "@type": "WebPage",
      "@id": "https://wahanatotalita.com/verifikasi/#webpage",
      "url": "https://wahanatotalita.com/verifikasi/",
      "name": "Panduan & Verifikasi Sertifikat K3 Online Kemnaker RI & BNSP",
      "description": "Panduan resmi cara cek keaslian sertifikat K3 Kemnaker RI (TemanK3) dan BNSP online. Portal verifikasi alumni Wahana Totalita, ciri sertifikat asli, dan perpanjangan lisensi K3."
    },
    {
      "@type": "FAQPage",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "Bagaimana cara cek keaslian sertifikat K3 Kemnaker RI?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Sertifikat dan Lisensi K3 Kemnaker RI dapat diverifikasi melalui portal resmi TemanK3 (temank3.kemnaker.go.id) pada menu Pemeriksaan Sertifikat/Lisensi dengan memasukkan nomor registrasi atau NIK pemegang."
          }
        },
        {
          "@type": "Question",
          "name": "Berapa lama masa berlaku sertifikat K3?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Secara umum, Surat Keputusan Penunjukan (SKP) dan Lisensi Kewenangan K3 dari Kemnaker RI serta Sertifikat Kompetensi BNSP memiliki masa berlaku 3 tahun dan dapat diperpanjang (renewal)."
          }
        },
        {
          "@type": "Question",
          "name": "Apakah sertifikat K3 yang sudah habis masa berlakunya masih bisa diperpanjang?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Bisa. Anda dapat mengajukan perpanjangan lisensi / sertifikat K3 melalui PJK3 resmi seperti Wahana Totalita dengan menyertakan salinan sertifikat lama, surat keterangan kerja dari perusahaan, dan dokumen persyaratan pendukung."
          }
        }
      ]
    }
  ]
}

inline_styles:
/* Modern styling consistent with Wahana Totalita tokens */
.verif-hero {
  background: linear-gradient(135deg, var(--brand, #103A5C) 0%, var(--brand-dark, #0B2C46) 100%);
  padding: 64px 0 54px;
  text-align: center;
  color: #ffffff;
}
.verif-hero .badge-tag {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(255,255,255,0.12);
  border: 1px solid rgba(255,255,255,0.22);
  color: #FDE8DA;
  font-size: 0.85rem;
  font-weight: 600;
  padding: 6px 16px;
  border-radius: 999px;
  margin-bottom: 16px;
}
.verif-hero h1 {
  font-size: clamp(1.8rem, 4vw, 2.7rem);
  font-weight: 800;
  line-height: 1.25;
  margin: 0 auto 16px;
  max-width: 820px;
}
.verif-hero p {
  font-size: 1.05rem;
  opacity: 0.9;
  max-width: 700px;
  margin: 0 auto 28px;
  line-height: 1.6;
}
.quick-nav {
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 20px;
}
.quick-nav a {
  background: rgba(255,255,255,0.15);
  color: #fff;
  text-decoration: none;
  font-size: 0.9rem;
  font-weight: 600;
  padding: 10px 18px;
  border-radius: 8px;
  border: 1px solid rgba(255,255,255,0.25);
  transition: all .2s ease;
}
.quick-nav a:hover {
  background: var(--accent, #F06A25);
  border-color: var(--accent, #F06A25);
  transform: translateY(-2px);
}

/* Sections */
.verif-section {
  padding: 56px 0;
}
.verif-section-alt {
  background: var(--surface-subtle, #F8FAFC);
}
.section-title {
  text-align: center;
  max-width: 720px;
  margin: 0 auto 36px;
}
.section-title h2 {
  font-size: clamp(1.5rem, 3vw, 2.1rem);
  color: var(--brand, #103A5C);
  margin-bottom: 10px;
  font-weight: 800;
}
.section-title p {
  color: var(--mut, #5A6B7B);
  font-size: 1rem;
  margin: 0;
}

/* Portal Grid */
.portal-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 28px;
  max-width: 1020px;
  margin: 0 auto;
}
.portal-card {
  background: #ffffff;
  border: 1px solid var(--border, #DCE6EE);
  border-radius: 16px;
  padding: 32px;
  box-shadow: 0 4px 18px rgba(16, 58, 92, 0.05);
  display: flex;
  flex-direction: column;
  position: relative;
  transition: transform .2s ease, box-shadow .2s ease;
}
.portal-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 10px 28px rgba(16, 58, 92, 0.1);
}
.portal-header {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 18px;
}
.portal-icon {
  width: 52px;
  height: 52px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.8rem;
  background: var(--brand-light, #E8F0F7);
}
.portal-card h3 {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--brand, #103A5C);
  margin: 0 0 4px;
}
.portal-card .portal-sub {
  font-size: 0.85rem;
  color: var(--mut, #5A6B7B);
  font-weight: 600;
}
.step-list {
  margin: 0 0 24px;
  padding-left: 0;
  list-style: none;
  font-size: 0.95rem;
  color: #334155;
  flex-grow: 1;
}
.step-list li {
  position: relative;
  padding-left: 32px;
  margin-bottom: 14px;
  line-height: 1.5;
}
.step-list li::before {
  content: counter(step-counter);
  counter-increment: step-counter;
  position: absolute;
  left: 0;
  top: 1px;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: var(--brand, #103A5C);
  color: #fff;
  font-size: 0.75rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
}
.portal-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  background: var(--brand, #103A5C);
  color: #fff;
  text-decoration: none;
  padding: 13px 20px;
  border-radius: 10px;
  font-weight: 700;
  font-size: 0.95rem;
  text-align: center;
  transition: all .2s ease;
}
.portal-btn:hover {
  background: var(--brand-mid, #16486E);
  color: #fff;
}
.portal-btn.btn-accent {
  background: var(--accent, #F06A25);
}
.portal-btn.btn-accent:hover {
  background: var(--accent-dark, #C2410C);
}

/* Local Search Box for Alumni */
.local-search-container {
  max-width: 680px;
  margin: 0 auto;
  background: #ffffff;
  border: 1px solid var(--border, #DCE6EE);
  border-radius: 16px;
  padding: 32px;
  box-shadow: 0 6px 24px rgba(0,0,0,0.04);
}
.local-search-box {
  display: flex;
  gap: 10px;
  margin-top: 16px;
}
@media (max-width: 640px) {
  .local-search-box {
    flex-direction: column;
  }
}
.local-search-box input {
  flex-grow: 1;
  padding: 14px 18px;
  border: 2px solid var(--border, #DCE6EE);
  border-radius: 10px;
  font-size: 1rem;
  font-family: monospace;
  text-transform: uppercase;
  letter-spacing: 1px;
}
.local-search-box input:focus {
  outline: none;
  border-color: var(--brand, #103A5C);
  box-shadow: 0 0 0 4px rgba(16, 58, 92, 0.08);
}
.local-search-box button {
  background: var(--accent, #F06A25);
  color: #fff;
  border: none;
  padding: 14px 24px;
  border-radius: 10px;
  font-size: 1rem;
  font-weight: 700;
  cursor: pointer;
  white-space: nowrap;
  transition: background .2s ease;
}
.local-search-box button:hover {
  background: var(--accent-dark, #C2410C);
}

/* Result Styles */
.result-box {
  margin-top: 24px;
  border-radius: 14px;
  padding: 24px;
  text-align: center;
}
.result-valid {
  background: #F0FDF4;
  border: 2px solid #059669;
}
.result-invalid {
  background: #FFF1F2;
  border: 2px solid #E11D48;
}
.cert-table {
  background: #ffffff;
  border-radius: 10px;
  border: 1px solid #E2E8F0;
  margin-top: 16px;
  padding: 14px 20px;
  text-align: left;
}
.cert-row {
  display: flex;
  justify-content: space-between;
  padding: 8px 0;
  border-bottom: 1px solid #F1F5F9;
  font-size: 0.92rem;
}
.cert-row:last-child {
  border-bottom: none;
}
.cert-row .lbl { color: #64748B; }
.cert-row .val { font-weight: 700; color: #0F172A; }

/* Features & Characteristics Grid */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 20px;
  max-width: 1040px;
  margin: 0 auto;
}
.feature-card {
  background: #ffffff;
  border: 1px solid var(--border, #DCE6EE);
  border-radius: 12px;
  padding: 22px;
  text-align: left;
}
.feature-card .feat-icon {
  font-size: 2rem;
  margin-bottom: 12px;
}
.feature-card h4 {
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--brand, #103A5C);
  margin: 0 0 8px;
}
.feature-card p {
  font-size: 0.88rem;
  color: var(--mut, #5A6B7B);
  line-height: 1.5;
  margin: 0;
}

/* CTA Banner */
.renewal-cta {
  background: linear-gradient(135deg, var(--brand-dark, #0B2C46) 0%, var(--brand, #103A5C) 100%);
  border-radius: 20px;
  padding: 48px 32px;
  color: #ffffff;
  text-align: center;
  max-width: 960px;
  margin: 0 auto;
  box-shadow: 0 12px 36px rgba(11, 44, 70, 0.15);
}
.renewal-cta h3 {
  font-size: clamp(1.6rem, 3.2vw, 2.3rem);
  font-weight: 800;
  margin: 0 0 14px;
}
.renewal-cta p {
  font-size: 1.05rem;
  opacity: 0.92;
  max-width: 680px;
  margin: 0 auto 28px;
  line-height: 1.6;
}
.cta-buttons {
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 16px;
}
.cta-btn-wa {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  background: #25D366;
  color: #ffffff;
  text-decoration: none;
  font-weight: 700;
  font-size: 1.05rem;
  padding: 14px 28px;
  border-radius: 12px;
  box-shadow: 0 4px 14px rgba(37, 211, 102, 0.35);
  transition: all .2s ease;
}
.cta-btn-wa:hover {
  background: #1EBE5B;
  color: #fff;
  transform: translateY(-2px);
}
.cta-btn-schedule {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  background: var(--accent, #F06A25);
  color: #ffffff;
  text-decoration: none;
  font-weight: 700;
  font-size: 1.05rem;
  padding: 14px 28px;
  border-radius: 12px;
  box-shadow: 0 4px 14px rgba(240, 106, 37, 0.35);
  transition: all .2s ease;
}
.cta-btn-schedule:hover {
  background: var(--accent-dark, #C2410C);
  color: #fff;
  transform: translateY(-2px);
}

/* FAQ Section */
.faq-wrap {
  max-width: 820px;
  margin: 0 auto;
}
.faq-item {
  background: #ffffff;
  border: 1px solid var(--border, #DCE6EE);
  border-radius: 12px;
  margin-bottom: 14px;
  padding: 20px 24px;
}
.faq-item h4 {
  margin: 0 0 10px;
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--brand, #103A5C);
}
.faq-item p {
  margin: 0;
  font-size: 0.95rem;
  color: #475569;
  line-height: 1.6;
}
